code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            r0 = min(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            shape = {(x-r0, y-c0) for x, y in cells}
            if shape == {(0,1),(1,0),(1,1),(1,2)}:
                counts["up"] += 1
            elif shape == {(0,0),(0,1),(0,2),(1,1)}:
                counts["down"] += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0,0),(2,0),(0,2),(2,2))
    for color, count, offset in ((3, counts["up"], 0), (1, counts["down"], 3)):
        for i, (r, c) in enumerate(slots[:count]):
            out[r][offset+c] = color
    return out
'''
